## CSP（内容安全策略）

**CSP（Content Security Policy）** 通过 HTTP 响应头或 `<meta>` 标签限制页面可以加载的资源类型和来源，有效防止 XSS 攻击。

```typescript
interface CSPDirectives {
  'default-src': string[];
  'script-src': string[];
  'style-src': string[];
  'img-src': string[];
  'connect-src': string[];
  'font-src': string[];
  'frame-src': string[];
  'report-uri'?: string[];
}

function buildCSP(directives: Partial<CSPDirectives>): string {
  return Object.entries(directives)
    .map(([key, values]) => `${key} ${values.join(' ')}`)
    .join('; ');
}

const csp = buildCSP({
  'default-src': ["'self'"],
  'script-src': ["'self'", "'nonce-abc123'"],
  'style-src': ["'self'", "'unsafe-inline'"],
  'img-src': ["'self'", 'data:', 'https://cdn.example.com'],
  'connect-src': ["'self'", 'https://api.example.com'],
  'font-src': ["'self'", 'https://fonts.gstatic.com'],
});
```

```mermaid
flowchart TD
    Page["页面加载资源"]
    Page --> Check{"CSP 检查"}
    Check --> Script{"script-src?"}
    Script -->|匹配| Allow1["允许加载"]
    Script -->|不匹配| Block1["阻止 + 报告"]
    Check --> Style{"style-src?"}
    Style -->|匹配| Allow2["允许加载"]
    Style -->|不匹配| Block2["阻止 + 报告"]
    Check --> Img{"img-src?"}
    Img -->|匹配| Allow3["允许加载"]
    Img -->|不匹配| Block3["阻止 + 报告"]
```

